{
  "typography": {
    "caption": {
      "fontSize": {
        "pointer": 11,
        "touch": 12
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 16
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "detail": {
      "fontSize": {
        "pointer": 12,
        "touch": 13
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "body": {
      "fontSize": {
        "pointer": 13,
        "touch": 15
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "label": {
      "fontSize": {
        "pointer": 14,
        "touch": 15
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "title": {
      "fontSize": {
        "pointer": 16,
        "touch": 16
      },
      "lineHeight": {
        "pointer": 24,
        "touch": 24
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "headline": {
      "fontSize": {
        "pointer": 20,
        "touch": 22
      },
      "lineHeight": {
        "pointer": 28,
        "touch": 28
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "display": {
      "fontSize": {
        "pointer": 26,
        "touch": 28
      },
      "lineHeight": {
        "pointer": 32,
        "touch": 36
      },
      "fontWeight": 600,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "shape": {
      "control": "{radius-control}",
      "container": "{radius-container}",
      "modal": "{radius-modal}"
    },
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 40
      },
      "density": {
        "pointer": {
          "pad": 12,
          "gap": 8
        },
        "touch": {
          "pad": 12,
          "gap": 8
        }
      },
      "item": {
        "pointer": {
          "inset": 4,
          "pad": 11
        },
        "touch": {
          "inset": 4,
          "pad": 11
        }
      },
      "control": {
        "pointer": {
          "padding": 6,
          "gap": 8,
          "dot": 12,
          "switch": "regular"
        },
        "touch": {
          "padding": 6,
          "gap": 8,
          "dot": 12,
          "switch": "regular"
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 32,
          "lg": 40
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 48
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "double",
      "width": 2,
      "offset": 0
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    },
    "control": {
      "field": "box-underline",
      "choice": "inset",
      "track": "hairline",
      "handle": "ring"
    }
  },
  "shape": {
    "curve": "circular",
    "corners": {
      "button": "radius"
    }
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0,
      "focus": 0,
      "pressed": 0,
      "dragged": 0
    },
    "pressed-opacity": 1,
    "rest-opacity": 0.5,
    "disabled": {
      "content": 0.36,
      "fill": true
    }
  },
  "transition": {
    "enter": {
      "duration": 250,
      "timingFunction": "decelerate"
    }
  },
  "motion": {
    "fast": {
      "duration": 83,
      "timingFunction": "decelerate"
    },
    "default": {
      "duration": 167,
      "timingFunction": "decelerate"
    },
    "slow": {
      "duration": 250,
      "timingFunction": "decelerate"
    },
    "state": {
      "duration": 83,
      "timingFunction": "decelerate"
    }
  },
  "finishes": {
    "shared": {
      "card": {
        "background": "{card}",
        "foreground": "{foreground}",
        "elevation": null
      },
      "inset": {
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{input}"
      },
      "channel": {
        "background": "{inset}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{border}"
      },
      "raised": {
        "background": "{raised}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "backdropFilter": "none",
        "material": null
      },
      "plate": {
        "background": "{card}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "elevation": null
      },
      "overlay": {
        "foreground": "{foreground}",
        "border-color": "{line}",
        "backdropFilter": "none",
        "material": "acrylic",
        "elevation": null
      },
      "modal": {
        "background": "{background}",
        "foreground": "{foreground}",
        "elevation": null
      },
      "inverse": {
        "background": "{inverse}",
        "foreground": "{inverse-foreground}",
        "border-color": "{line}",
        "backdropFilter": "none",
        "material": null,
        "elevation": null
      },
      "glass": {
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{line}",
        "backdropFilter": "blur(30px)",
        "material": null,
        "elevation": null
      },
      "accent": {
        "background": "{primary}",
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "border-bottom-color": "{brand-edge}",
        "pressed-opacity": 1
      },
      "fill": {
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "background": "{primary}",
        "gradient": null
      },
      "knob": {
        "shadow": "none",
        "foreground": "{foreground}",
        "background": "{knob}",
        "gradient": null,
        "border-color": "transparent",
        "checked-background": "{primary-foreground}"
      },
      "hover": {
        "shadow": "none",
        "foreground": "{foreground}",
        "background": "{hover}",
        "border-color": "{border}",
        "elevation": null
      },
      "pressed": {
        "shadow": "none",
        "foreground": "{muted-foreground}",
        "background": "{muted}",
        "border-color": "{border}",
        "elevation": null
      },
      "disabled": {
        "shadow": "none",
        "border-color": "{border}"
      }
    },
    "light": {
      "card": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 4px 8px oklch(0 0 0 / 0.14)",
        "border-color": "oklch(0.92191 0 0)"
      },
      "raised": {
        "border-top-color": "{border}",
        "border-bottom-color": "oklch(0.84522 0 0)"
      },
      "overlay": {
        "background": "oklch(from {popover} l c h / 0.85)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 16px 32px oklch(0 0 0 / 0.24)"
      },
      "modal": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 64px 128px oklch(0 0 0 / 0.24)",
        "border-color": "oklch(0.81093 0 0)"
      },
      "inverse": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.2), 0 16px 32px oklch(0 0 0 / 0.24)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.85)"
      },
      "accent": {
        "border-color": "oklch(0.52768 0.14982 252.341)",
        "pressed-background": "oklch(0.5773 0.13223 250.006)",
        "pressed-foreground": "oklch(0.87245 0.03754 247.003)"
      },
      "fill": {
        "border-color": "oklch(0.52768 0.14982 252.341)"
      },
      "hover": {
        "border-top-color": "{border}",
        "border-bottom-color": "oklch(0.84522 0 0)"
      },
      "disabled": {
        "background": "oklch(0.97015 0 0)",
        "foreground": "oklch(0.68949 0 0)"
      }
    },
    "dark": {
      "card": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 4px 8px oklch(0 0 0 / 0.28)",
        "border-color": "oklch(0.23075 0 0)"
      },
      "raised": {
        "border-top-color": "oklch(0.32897 0 0)",
        "border-bottom-color": "{border}"
      },
      "overlay": {
        "background": "oklch(from {popover} l c h / 0.96)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)"
      },
      "modal": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 64px 128px oklch(0 0 0 / 0.48)",
        "border-color": "oklch(0.37909 0 0)"
      },
      "inverse": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.96)"
      },
      "accent": {
        "border-color": "oklch(0.81732 0.11439 230)",
        "pressed-background": "oklch(0.70029 0.10192 230.522)",
        "pressed-foreground": "oklch(0.42706 0.05878 229.834)"
      },
      "fill": {
        "border-color": "oklch(0.81732 0.11439 230)"
      },
      "hover": {
        "border-top-color": "oklch(0.32897 0 0)",
        "border-bottom-color": "{border}"
      },
      "disabled": {
        "background": "oklch(0.28502 0 0)",
        "foreground": "oklch(0.54863 0 0)"
      }
    }
  },
  "elevation": {
    "light": {
      "sm": null,
      "md": "0 0 2px oklch(0 0 0 / 0.12), 0 4px 8px oklch(0 0 0 / 0.14)",
      "lg": "0 0 8px oklch(0 0 0 / 0.2), 0 16px 32px oklch(0 0 0 / 0.24)",
      "xl": "0 0 8px oklch(0 0 0 / 0.2), 0 64px 128px oklch(0 0 0 / 0.24)",
      "inset": null
    },
    "dark": {
      "sm": null,
      "md": "0 0 2px oklch(0 0 0 / 0.24), 0 4px 8px oklch(0 0 0 / 0.28)",
      "lg": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)",
      "xl": "0 0 8px oklch(0 0 0 / 0.4), 0 64px 128px oklch(0 0 0 / 0.48)",
      "inset": null
    }
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "WinUI 3 (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never add a finish field a role does not use: the fields of `finish.<role>` are the ones `packages/theme/finish-fields.ts` lists, and every theme states them the same way."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "WinUI 3 (`winui3/release/2.7.0`): Windows 11 fill and stroke resources composited over `SolidBackgroundFillColorBase` (`#F3F3F3` light / `#202020` dark) with `#0078D4` accent, double focus strokes, and deterministic timing curves.",
        "elevation": "WinUI 3 ThemeShadow depths (2/8/16/32/128) paired with composited `ControlStrokeColorDefault` / `SurfaceStrokeColorDefault` borders and `material.windows` blur on `glass`, `menu`, and `tooltip` (`AcrylicInAppFillColorDefault` 0.85 light / 0.96 dark).",
        "dos": [
          "Use `4px` `ControlCornerRadius` for `control` and `8px` `OverlayCornerRadius` for `container` and `modal` with `shape.curve: \"circular\"`.",
          "Use `focus.style: \"double\"` (2px outer `FocusStrokeColorOuter` + 1px inner `FocusStrokeColorInner`) and WinUI timing motion (`decelerate` / `point-to-point`).",
          "Use underlined tabs and fields with leading navigation bar indicators."
        ],
        "donts": [
          "Do not substitute continuous squircle corners for WinUI 3's circular corners."
        ]
      },
      "contrast": {
        "waivers": [
          {
            "fg": "finish.accent.pressed-foreground",
            "bg": "finish.accent.pressed-background",
            "source": "WinUI TextOnAccentFillColorSecondary on AccentFillColorTertiary, while pressed"
          }
        ]
      },
      "scales": {
        "citations": {
          "dimension.size.control.pointer.padding": "WinUI 3 button padding 6px (`Button_themeresources.xaml`)",
          "dimension.size.control.touch.padding": "WinUI 3 button padding 6px (`Button_themeresources.xaml`)",
          "dimension.size.item.pointer.pad": "WinUI 3 menu row text padding 11px (`MenuFlyoutItemThemePadding` 11,8,11,9, `MenuFlyout_themeresources.xaml`)",
          "dimension.size.item.touch.pad": "WinUI 3 menu row text padding 11px (the same padding on touch)",
          "dimension.size.hit.touch": "Windows touch target 40x40 epx (Touch interactions, \"Target size\")"
        }
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "WinUI 3 type weights (400 and 600 only); sizes follow the shared scale (ADR 0009).",
    "caption": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.caption}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.label}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.label}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Control labels, form labels, and interactive triggers."
    },
    "title": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.title}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.title}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Card and section headings."
    },
    "headline": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.headline}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.headline}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Page-level headings."
    },
    "display": {
      "$value": {
        "fontFamily": "system-ui",
        "fontSize": "{font.size.display}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.display}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Large display numerals and hero headings."
    }
  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "shape": {
      "$type": "dimension",
      "$description": "Semantic corner radius roles by layer, referencing base dimension.radius.* tokens.",
      "control": {
        "$value": "{dimension.radius.control}",
        "$description": "Corner radius for in-page elements: buttons, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": "{dimension.radius.container}",
        "$description": "Corner radius for containers and overlays: cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": "{dimension.radius.modal}",
        "$description": "Corner radius for modal surfaces: dialogs, sheets, and drawers."
      }
    },
    "stroke": {
      "$description": "Border stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline width for dividers, container edges (cards, drawers, overlays) and outlined variants."
      },
      "control": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Interactive control border width."
      }
    },
    "focus": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "style": "double"
        }
      },
      "$description": "WinUI 3 double focus stroke (2px outer FocusStrokeColorOuter + 1px inner FocusStrokeColorInner, 0px offset).",
      "width": {
        "$value": {
          "value": 2,
          "unit": "px"
        },
        "$description": "2px outer focus stroke width per WinUI 3."
      },
      "offset": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Focus ring outward offset from control bounds."
      }
    },
    "control": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "field": "box-underline",
          "choice": "inset",
          "track": "hairline",
          "handle": "ring"
        }
      },
      "$description": "WinUI 3 control dimensions: TextBox's box-underline, inset selection controls, a hairline track and a ring knob (docs/specs/theme-contract-v2.md §11.2)."
    },
    "radius": {
      "$type": "dimension",
      "$description": "WinUI 3 corner radius scale: ControlCornerRadius 4px (control) and OverlayCornerRadius 8px (container and modal).",
      "control": {
        "$value": {
          "value": 4,
          "unit": "px"
        },
        "$description": "Corner radius for in-page controls, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for dialogs, sheets, and drawers."
      }
    },
    "size": {
      "$description": "Ergonomic sizing scales for pointer input.",
      "hit": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Minimum hit target size (0 disables padding expansion)."
      },
      "density": {
        "$description": "Page-level padding and gap.",
        "pad": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
        }
      },
      "item": {
        "$description": "WinUI 3 menu rows: the fill 4px in from the flyout's edge (MenuFlyoutItemMargin 4,2,4,2) and the text 11px inside it (MenuFlyoutItemThemePadding 11,8,11,9; ComboBoxItemThemePadding 11,5,11,7), the same with a pen or a finger (microsoft-ui-xaml MenuFlyout_themeresources.xaml).",
        "inset": {
          "$value": {
            "value": 4,
            "unit": "px"
          }
        },
        "pad": {
          "$value": {
            "value": 11,
            "unit": "px"
          }
        }
      },
      "control": {
        "$extensions": {
          "dev.aning.shadcn-nsh": {
            "switch": "regular"
          }
        },
        "$description": "Control internal spacing and switch size tier.",
        "padding": {
          "$value": {
            "value": 6,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
